const code = `import json, subprocess, sys
from pathlib import Path
sys.path.insert(0, "tools")
from i18nlib.config import load_manifest
from i18nlib.locale_model import LocaleLoader
from i18nlib.runtime import LuaRuntime

loader = LocaleLoader(LuaRuntime(load_manifest()))
workset = json.loads(Path(".ai/task/repair-w53-20260929/WORKSET.json").read_text(encoding="utf-8"))["items"]
sync_doc = json.loads(Path(".ai/task/repair-w53-20260929/RUNTIME-SYNC.json").read_text(encoding="utf-8"))
sync = sync_doc["items"][0]
expected_workset = {(x["normalized_path"], x["section"], x["source"], x.get("source_tag")) for x in workset}
sync_key = (sync["file"], sync["section"], sync["source"], sync.get("source_tag"))
expected = expected_workset | {sync_key}
changed = set()
counts = {}
current = {}
for path in ("mod-tome.lua", "tome-orcs.lua"):
    old = loader.load_bytes(subprocess.run(["git", "show", f"HEAD:{path}"], check=True, stdout=subprocess.PIPE).stdout, logical_path=path).translations
    new = loader.load_path(Path(path), logical_path=path).translations
    assert len(old) == len(new), (path, len(old), len(new))
    count = 0
    for index, (before, after) in enumerate(zip(old, new)):
        for field in ("kind", "function_name", "section", "source", "source_tag", "args_order", "special"):
            assert before.get(field) == after.get(field), (path, index, field, before.get(field), after.get(field))
        key = (path, after.get("section"), after.get("source"), after.get("source_tag"))
        current[key] = after
        if before.get("target") != after.get("target"):
            changed.add(key)
            count += 1
    counts[path] = {"loaded_records": len(new), "changed_targets": count}
assert counts["mod-tome.lua"]["changed_targets"] == 17, counts
assert counts["tome-orcs.lua"]["changed_targets"] == 2, counts
assert len(expected_workset) == 18, len(expected_workset)
assert len(expected) == 19, len(expected)
assert changed == expected, {"missing": sorted(expected - changed), "extra": sorted(changed - expected)}
sibling_key = ("mod-tome.lua", "mod-tome/data/zones/shertul-fortress/grids.lua", sync["source"], sync.get("source_tag"))
assert current[sync_key]["target"].encode("utf-8") == sync["new_target"].encode("utf-8")
assert current[sync_key]["target"].encode("utf-8") == current[sibling_key]["target"].encode("utf-8")
print(json.dumps({
    "runtime": "manifest LuaJIT via LocaleLoader",
    "baseline": "HEAD",
    "files": counts,
    "workset_changed_targets": len(expected_workset),
    "runtime_sync_changed_targets": 1,
    "changed_set_exact": True,
    "non_target_fields_unchanged": True,
    "sync_target_equals_runtime_sync_new_target_bytes": True,
    "sync_target_equals_reviewed_sibling_target_bytes": True
}, ensure_ascii=False, sort_keys=True))`;
const quoted = "'" + code.replace(/'/g, "'\\''") + "'";
const results = await Promise.all([
  tools.exec_command({cmd:`python3 -B -c ${quoted}`,workdir:"/workspace/tome4-chinese-translation",yield_time_ms:30000,max_output_tokens:12000,sandbox_permissions:"require_escalated",justification:"允许我运行只读的 manifest LuaJIT/LocaleLoader 有界语义比较，验证相对 HEAD 的 17/2 条 target 差异与字节一致性吗？"}),
  tools.exec_command({cmd:"python3 -B tools/i18n lint --strict",workdir:"/workspace/tome4-chinese-translation",yield_time_ms:30000,max_output_tokens:20000,sandbox_permissions:"require_escalated",justification:"允许我运行本次 RUNTIME-SYNC 要求的 strict lint 吗？","prefix_rule":["python3","-B","tools/i18n","lint"]}),
  tools.exec_command({cmd:"git diff --check",workdir:"/workspace/tome4-chinese-translation",yield_time_ms:30000,max_output_tokens:12000,sandbox_permissions:"require_escalated",justification:"允许我运行本次 RUNTIME-SYNC 要求的 git diff 空白检查吗？","prefix_rule":["git","diff","--check"]})
]);
results.forEach((r,i)=>text(JSON.stringify({validation:i+1,exit_code:r.exit_code,output:r.output})));

